package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The due-by a claim of the person on the date is fixed with when it is created: the terms-th business day after its
 * date — skipping Saturdays, Sundays and the sheet's holidays (as the list stands now) — for the person's own terms,
 * else those of their grade, else the sheet's, each as in force on that date. */
public final class NewDueBy {

    private NewDueBy() {
    }

    public static LocalDate of(LocalDate date, Person person, SettingRepository settings,
            HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date,
                person.termsOn(settings.dated(person.sheetId()), date));
    }
}
 * due fixed when the claim was settled, or null while it is live (not settled, or settled with no rate).
 * {@code openedBy} is the user who opened the claim, or null while it is a draft. {@code stated} is whether
 * its person's last statement bound it to a figure, {@code statedDue} (null: n/a) — it then shows and totals
 * that figure, not its live one. {@code number} is sheet-wide (1, 2, ...) or, under period numbering,
 * within its period (P1-1, X-1). {@code corrects} is, for a correction, the number of the claim it corrects (null:
 * not a correction). {@code dueBy} is fixed when the claim is created: the terms-th business day after its date (skipping Saturdays,
 * Sundays and the sheet's holidays) for its person's own terms, else those of their grade, else the sheet's, each in
 * force on that date; it does not change when the terms or its date change later. While PENDING the claim is not bound: it shows and totals its live figure, and is bound again
 * once rejected (back to OPEN) when the statement included it. {@code deferredUntil} is the date an OPEN claim is
 * deferred until (null: never deferred): while the sheet's today is before it the claim is {@link #deferred deferred}.
 * {@code proofs} is how many proofs the claim has been given. {@code splitFrom} is the number of the claim it was split
 * off (null: not split off another claim).
 */

    /** The sheet's terms in days in force on the date. */
    public int termsOn(LocalDate date) {
        String value = on(TERMS, date);
        return value == null ? SettingRepository.DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms in force on the date (null: none, the sheet's terms). */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = on(gradeTerms(grade), date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The terms in days for a claim of the grade dated on the date: the grade's own in force then, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The grades' own terms in force on the date, by grade (a grade with none left out). */
    public Map<String, Integer> gradeTermsOn(LocalDate date) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        values.keySet().stream().filter((k) -> k.startsWith(TERMS + "-")).sorted().forEach((key) -> {
            String grade = key.substring(TERMS.length() + 1);
            Integer own = gradeTermsOn(grade, date);
            if (own != null) {
                terms.put(grade, own);
            }
        });
        return terms;
    }

    /** The clerk limit in force on the date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        String value = on(CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The cap in force on the date (null: no cap). */
    public BigDecimal capOn(LocalDate date) {
        String value = on(CAP, date);

